<script module lang="ts">
/**
 * A single keyboard key, drawn as a keycap (`design/components/kbd.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/kbd.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/kbd.module.css'

export interface KbdProps {
  /**
   * One key; `⌘` and `K` are two keys.
   */
  children: Snippet
}
</script>

<script lang="ts">
let { children }: KbdProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<kbd class={styles.kbd} data-member="kbd">{@render children?.()}</kbd
>{/if
}{@render joined.end?.()}
